function loadOne(k){var b=biz();var q=sb().from(T[k]).select('*').eq('business_id',b.id);if(k==='curriculum'||k==='school_profile')return q.maybeSingle().then(function(r){if(r.error)throw r.error;data[k]=r.data||null});return q.order('created_at',{ascending:false}).limit(500).then(function(r){if(r.error)throw r.error;data[k]=r.data||[]}).catch(function(err){if(k==='progression'&&(err.code==='42P01'||err.code==='PGRST205'||/school_student_movements|schema cache/i.test(err.message||''))){data[k]=[];return}throw err})}
function load(){return Promise.all(Object.keys(T).map(loadOne)).then(function(){var client=sb();return Promise.all(['students','staff'].map(function(k){return Promise.all((data[k]||[]).map(function(row){if(!row.photo_path)return Promise.resolve();return client.storage.from('school-people-photos').createSignedUrl(row.photo_path,3600).then(function(res){if(!res.error&&res.data)row.photo_url=res.data.signedUrl})}))}))})}
function tbl(head,rows){return '<div class="wls-table-wrap"><table class="wls-table"><thead><tr>'+head.map(function(x){return '<th>'+x+'</th>'}).join('')+'</tr></thead><tbody>'+(rows||'<tr><td colspan="'+head.length+'" class="wls-empty">No records yet. Add your first record to get started.</td></tr>')+'</tbody></table></div>'}
function downloadSchoolRecords(format){
var business=biz(),client=sb(),status=document.getElementById('wlsSchoolExportStatus');
if(!business||!business.id||!client){alert('Sign in to the school workspace before exporting.');return}
var role=String(business.role||'member').toLowerCase();
if(!['owner','admin','manager'].includes(role)){alert('Only school owners, administrators and authorised managers can export school records.');return}
var buttons=document.querySelectorAll('[data-school-export]');buttons.forEach(function(b){b.disabled=true});
if(status)status.textContent='Preparing a secure export from the cloud. Please keep this page open…';
var names=Object.keys(T),records={},counts={},failed=[];
function fetchTable(key){
var table=T[key],page=0,size=1000,all=[];
function next(){return client.from(table).select('*').eq('business_id',business.id).range(page,page+size-1).then(function(res){if(res.error)throw res.error;var batch=res.data||[];all=all.concat(batch);if(batch.length===size){page+=size;return next()}return all})}
return next().then(function(rows){records[table]=rows;counts[table]=rows.length}).catch(function(err){if(key==='progression'&&(err.code==='42P01'||err.code==='PGRST205'||/school_student_movements|schema cache/i.test(err.message||''))){records[table]=[];counts[table]=0;return}failed.push({table:table,error:err.message||String(err)});throw err})
}
return names.reduce(function(chain,key){return chain.then(function(){return fetchTable(key)})},Promise.resolve()).then(function(){
if(failed.length)throw new Error('Could not export '+failed.map(function(x){return x.table}).join(', ')+'. No partial export was downloaded.');
var profile=records[T.school_profile]||[],schoolName=(profile[0]&&profile[0].school_name)||business.name||'School',stamp=new Date().toISOString(),slug=String(schoolName).toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'school';
var payload={format:'White Lion School Records Export',version:1,school:{business_id:business.id,name:schoolName},exported_at:stamp,record_counts:counts,records:records};
function save(blob,name){var url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(url)},1500)}
if(format==='json'){save(new Blob([JSON.stringify(payload,null,2)],{type:'application/json;charset=utf-8'}),slug+'-complete-school-records-'+stamp.slice(0,10)+'.json')}
else{var all=[],columns=new Set(['record_category']);Object.keys(records).forEach(function(table){records[table].forEach(function(row){var item=Object.assign({record_category:table},row);all.push(item);Object.keys(item).forEach(function(k){columns.add(k)})})});var cols=Array.from(columns),cell=function(v){var x=v==null?'':typeof v==='object'?JSON.stringify(v):String(v);if(/^[=+\-@\t\r]/.test(x))x="'"+x;return '"'+x.replace(/"/g,'""')+'"'};var csv='\uFEFF'+cols.map(cell).join(',')+'\r\n'+all.map(function(row){return cols.map(function(k){return cell(row[k])}).join(',')}).join('\r\n');save(new Blob([csv],{type:'text/csv;charset=utf-8'}),slug+'-complete-school-records-'+stamp.slice(0,10)+'.csv')}
var total=Object.keys(counts).reduce(function(n,k){return n+counts[k]},0);if(status)status.textContent=total+' records exported across '+names.length+' school record categories. Export is restricted to '+schoolName+'.';if(window.toast)window.toast('School records downloaded successfully')
}).catch(function(err){if(status)status.textContent='Export failed: '+(err.message||String(err))+'. No partial file was created.';alert(err.message||'Unable to export school records')}).finally(function(){buttons.forEach(function(b){b.disabled=false})})
}
