if(tab==='student_accounts'){var profile=data.school_profile||{},portal=profile.portal_code?new URL('student-portal.html',location.href):null;if(portal)portal.searchParams.set('school',profile.portal_code);return '<div class="wls-panel"><div class="wls-panel-head"><div><h3>Student Portal activation register</h3><div class="wls-muted">Each student uses their own registered email, verifies it, and activates their Student ID automatically.</div></div><span class="wls-pill">'+s.filter(function(x){return !!x.user_id}).length+' activated / '+s.filter(function(x){return x.status==='active'}).length+' active students</span></div><div class="wls-alert">Add each student’s own email to their school record. Share the permanent Student Portal link. Students create their own password, verify their email, and their account is linked automatically. Email and password are used for sign-in; the Student ID identifies their school record.</div><h3 style="margin-top:16px">Student activation register</h3>'+tbl(['Student ID','Student name','Class','Student email','Account status','Action'],s.map(function(x){var cl=(data.classes||[]).find(function(y){return y.id===x.class_id})||{};return '<tr><td>'+esc(x.admission_number)+'</td><td>'+esc(x.first_name+' '+x.last_name)+'</td><td>'+esc(cl.name||'—')+'</td><td>'+esc(x.student_email||'Not recorded')+'</td><td><span class="wls-pill">'+(x.user_id?'Active':x.student_email?'Awaiting student verification':'Email required')+'</span></td><td>'+(x.user_id?'Activated':'<button class="wls-btn alt" type="button" data-set-student-email="'+esc(x.id)+'">'+(x.student_email?'Update email':'Add student email')+'</button>')+'</td></tr>'}).join(''))+'<div class="wls-panel" style="margin-top:14px"><h3>Permanent Student Portal link</h3><input id="wlsStudentPortalUrl" class="wls-search" style="width:100%;max-width:100%" readonly value="'+esc(portal?portal.href:'Save the school profile first to generate the portal link')+'"><div class="wls-actions"><button class="wls-btn alt" type="button" id="wlsCopyStudentPortal" '+(portal?'':'disabled')+'>Copy Student Portal link</button><button class="wls-btn alt" type="button" id="wlsOpenStudentPortal" '+(portal?'':'disabled')+'>Open Student Portal ↗</button></div></div></div>'}

